/**
 * Calculate the amount of a line after its discount.
 * @param {number} lineTotal - Total before discount
 * @param {number} discountPercent - Discount percentage
 * @returns {number} Amount after discount in cents
 */
function lineAmountAfterDiscount(lineTotal, discountPercent) {
  const discount = calculateLineDiscount(lineTotal, discountPercent);
  return lineTotal - discount;
}

